from datetime import datetime, timedelta


class Appointment:
    def __init__(self, appointment_id, patient, doctor, start, end):
        self.appointment_id = appointment_id
        self.patient = patient
        self.doctor = doctor
        self.start = start
        self.end = end
        self.cancelled = False
        self.cancel_time = None


class Scheduler:
    def __init__(self) -> None:
        self._appointments = {}
        self._next_id = 0

    @staticmethod
    def _overlaps(a_start, a_end, b_start, b_end):
        return a_start < b_end and b_start < a_end

    def _slot_blocked(self, doctor, start, end, now):
        for appt in self._appointments.values():
            if appt.doctor != doctor:
                continue
            if not self._overlaps(start, end, appt.start, appt.end):
                continue
            if not appt.cancelled:
                return True
            # Cancelled appointment: does it still block?
            if appt.cancel_time is None:
                return True
            # Cancel less than 24h before start -> slot stays blocked
            if appt.cancel_time < appt.start - timedelta(hours=24):
                continue
            return True
        return False

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        return not self._slot_blocked(doctor, start, end, None)

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        if not (start < end):
            raise ValueError("Appointment start must be before end")

        # Patient can have at most one upcoming appointment
        for appt in self._appointments.values():
            if appt.patient != patient:
                continue
            if appt.cancelled:
                continue
            if appt.end > now:
                raise ValueError(
                    f"Patient {patient!r} already has an upcoming appointment"
                )

        if self._slot_blocked(doctor, start, end, now):
            raise ValueError(
                f"Slot for doctor {doctor!r} is not free"
            )

        appt = Appointment(self._next_id, patient, doctor, start, end)
        self._appointments[self._next_id] = appt
        self._next_id += 1
        return appt.appointment_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        appt = self._appointments.get(appointment_id)
        if appt is None:
            raise ValueError(f"No appointment with id {appointment_id}")
        if appt.cancelled:
            return
        appt.cancelled = True
        appt.cancel_time = now
